questions.question_text:
Solve $3x-4\ge8$. Which number line shows the solution?
[tikz]
\begin{tikzpicture}
\node[left] at (-1.85,0) {$A$};
\draw[{Stealth}-{Stealth}] (-1.7,0)--(2.6,0);
\foreach \v in {-3,...,5} {\draw (0.45*\v,0.08)--(0.45*\v,-0.08); \node[below,font=\tiny] at (0.45*\v,-0.1) {$\v$};}
\draw[very thick,-{Stealth}] (1.8,0)--(2.4,0);
\fill (1.8,0) circle (2.4pt);
\node[left] at (-1.85,-1.3) {$B$};
\draw[{Stealth}-{Stealth}] (-1.7,-1.3)--(2.6,-1.3);
\foreach \v in {-3,...,5} {\draw (0.45*\v,-1.22)--(0.45*\v,-1.38); \node[below,font=\tiny] at (0.45*\v,-1.4) {$\v$};}
\draw[very thick,-{Stealth}] (1.8,-1.3)--(2.4,-1.3);
\draw[fill=white] (1.8,-1.3) circle (2.4pt);
\node[left] at (-1.85,-2.6) {$C$};
\draw[{Stealth}-{Stealth}] (-1.7,-2.6)--(2.6,-2.6);
\foreach \v in {-3,...,5} {\draw (0.45*\v,-2.52)--(0.45*\v,-2.68); \node[below,font=\tiny] at (0.45*\v,-2.7) {$\v$};}
\draw[very thick,-{Stealth}] (1.8,-2.6)--(-1.5,-2.6);
\fill (1.8,-2.6) circle (2.4pt);
\node[left] at (-1.85,-3.9) {$D$};
\draw[{Stealth}-{Stealth}] (-1.7,-3.9)--(2.6,-3.9);
\foreach \v in {-3,...,5} {\draw (0.45*\v,-3.82)--(0.45*\v,-3.98); \node[below,font=\tiny] at (0.45*\v,-4) {$\v$};}
\draw[very thick,-{Stealth}] (1.8,-3.9)--(-1.5,-3.9);
\draw[fill=white] (1.8,-3.9) circle (2.4pt);
\end{tikzpicture}
[/tikz]
